class Solution {
    public int sumOfEncryptedInt(int[] nums) {
        int total = 0;
        for (int x : nums) {
            String s = String.valueOf(x);
            char d = '0';
            for (char c : s.toCharArray()) if (c > d) d = c;
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < s.length(); i++) sb.append(d);
            total += Integer.parseInt(sb.toString());
        }
        return total;
    }
}

var sumOfEncryptedInt = function(nums) {
    let total = 0;
    for (const x of nums) {
        const s = String(x);
        let d = '0';
        for (const c of s) if (c > d) d = c;
        total += Number(d.repeat(s.length));
    }
    return total;
};
